# ── Caché en memoria (estado interno del módulo) ──────────────────────────────
_CROWN_CACHE = {}


_SHARED_ICON = None


# ── Funciones públicas ────────────────────────────────────────────────────────

def get_embedded_logo():
    try:
        return Image.open(BytesIO(base64.b64decode(LOGO_B64)))
    except Exception:
        return None


def get_crown_image(size=40):
    """Devuelve la imagen de la corona (blanco, fondo transparente) como PhotoImage."""
    try:
        img = Image.open(BytesIO(base64.b64decode(CORONA_B64))).convert("RGBA")
        img.thumbnail((size, size), Image.LANCZOS)
        return ImageTk.PhotoImage(img)
    except Exception:
        return None


def get_crown_tk(size=40):
    """Devuelve un PhotoImage cacheado de la corona a tamaño 'size'."""
    if size not in _CROWN_CACHE:
        _CROWN_CACHE[size] = get_crown_image(size)
    return _CROWN_CACHE[size]


def get_window_icon():
    try:
        img = Image.open(BytesIO(base64.b64decode(ICON32_B64)))
        return ImageTk.PhotoImage(img)
    except Exception:
        return None


def _apply_icon(win):
    """Aplica el icono compartido a cualquier ventana Tk/Toplevel."""
    global _SHARED_ICON
    if _SHARED_ICON is None:
        _SHARED_ICON = get_window_icon()
    if _SHARED_ICON:
        win.iconphoto(True, _SHARED_ICON)


def resource_path(relative_path):  # noqa: F841  # used by PyInstaller at runtime
    if hasattr(sys, '_MEIPASS'):
        return os.path.join(sys._MEIPASS, relative_path)
    return os.path.join(relative_path)
